type ServerConfig struct {
	RunAddr         string `json:"server_address" env:"SERVER_ADDRESS"`
	RedirectBaseURL string `json:"base_url" env:"BASE_URL"`
	FileStoragePath string `json:"file_storage_path" env:"FILE_STORAGE_PATH"`
	DatabaseDSN     string `json:"database_dsn" env:"DATABASE_DSN"`
	Secret          string `json:"-" env:"SECRET"`
	Config          string `json:"-" env:"CONFIG"`
	TLSCertPath     string `json:"tls_cert_path" env:"TLS_CERT_PATH"`
	TLSKeyPath      string `json:"tls_key_path" env:"TLS_KEY_PATH"`
	TrustedSubnet   string `json:"trusted_subnet" env:"TRUSTED_SUBNET"`
	GRPCPort        string `json:"grpc_port" env:"GRPC_PORT"`
	EnableHTTPS     bool   `json:"enable_https" env:"ENABLE_HTTPS"`
	ProfileMode     bool   `json:"profile_mode" env:"PROFILE_MODE"`
}

var config ServerConfig

func ParseFlags() (*ServerConfig, error) {
	flag.StringVar(&config.RunAddr, "a", ":8080", "address and port to run server")
	flag.BoolVar(&config.EnableHTTPS, "s", false, "enable https")
	flag.BoolVar(&config.ProfileMode, "p", false, "register pprof profiler")
	flag.StringVar(&config.RedirectBaseURL, "b", "http://localhost:8080", "server URI prefix")
	flag.StringVar(&config.FileStoragePath, "f", "", "file storage path")
	flag.StringVar(&config.DatabaseDSN, "d", "", "Data Source Name (DSN)")
	flag.StringVar(&config.Secret, "e", "b4952c3809196592c026529df00774e46bfb5be0", "Secret")
	flag.StringVar(&config.Config, "c", "", "Config json file path")
	flag.StringVar(&config.TLSCertPath, "l", "./certs/cert.pem", "path to tls cert file")
	flag.StringVar(&config.TLSKeyPath, "k", "./certs/private.pem", "path to tls key file")
	flag.StringVar(&config.TrustedSubnet, "t", "", "trusted CIDR (ex. 192.168.0.0/24)")
	flag.StringVar(&config.GRPCPort, "grpc", "", "will add listener to port if specified")
	flag.Parse()

	if err := env.Parse(&config); err != nil {
		return nil, fmt.Errorf("error parsing env variables: %w", err)
	}

	if config.Config != "" {
		data, err := os.ReadFile(config.Config)
		if err != nil {
			return nil, fmt.Errorf("error opening config file: %w", err)
		}

		var configFromFile ServerConfig
		if err := json.NewDecoder(bytes.NewReader(data)).Decode(&configFromFile); err != nil {
			return nil, fmt.Errorf("error parsing json file config: %w", err)
		}

		if err := mergo.Merge(&config, configFromFile); err != nil {
			return nil, fmt.Errorf("cannot merge configs: %w", err)
		}
	}

	return &config, nil
}

// Модуль аутентификации клиентских запросов.
package auth

import (
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/golang-jwt/jwt/v4"
	"github.com/google/uuid"
	"go.uber.org/zap"
)

type Claims struct {
	jwt.RegisteredClaims
	UserID string
}

const (
	tokenExp   = time.Hour * 3
	maxAge     = 3600 * 24 * 30
	CookieName = "jwt-token"
	UserIDKey  = "userID"
)

var ErrTokenNotValid = errors.New("token is not valid")
var ErrNoUserInToken = errors.New("no user data in token")
var ErrBuildJWTString = errors.New("error building JWT string")

func BuildJWTString(secret string, userID string) (string, error) {
	token := jwt.NewWithClaims(jwt.SigningMethodHS256, Claims{
		RegisteredClaims: jwt.RegisteredClaims{
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(tokenExp)),
		},
		UserID: userID,
	})

	tokenString, err := token.SignedString([]byte(secret))
	if err != nil {
		return "", fmt.Errorf("error creating signed JWT: %w", err)
	}

	// возвращаем строку токена
	return tokenString, nil
}

func GetUserID(tokenString string, secret string) (string, error) {
	claims := &Claims{}
	token, err := jwt.ParseWithClaims(tokenString, claims,
		func(t *jwt.Token) (interface{}, error) {
			return []byte(secret), nil
		})
	if err != nil {
		if !token.Valid {
			return "", ErrTokenNotValid
		} else {
			return "", errors.New("parsing error")
		}
	}

	if claims.UserID == "" {
		return "", ErrNoUserInToken
	}

	return claims.UserID, nil
}

func NewAuthMiddleware(secret string, logger *zap.SugaredLogger) (gin.HandlerFunc, error) {
	if secret == "" {
		return nil, fmt.Errorf("empty secret for signing token")
	}

	return func(c *gin.Context) {
		cookie, err := c.Cookie(CookieName)
		if err != nil {
			if errors.Is(err, http.ErrNoCookie) {
				token, err := BuildJWTString(secret, uuid.New().String())
				if err != nil {
					logger.Error(ErrBuildJWTString, err)
					c.AbortWithStatus(http.StatusInternalServerError)
					return
				}
				c.SetCookie(CookieName, token, maxAge, "", "", false, true)
				cookie = token
			} else {
				logger.Error("Error reading cookie[%v]: %v", CookieName, err)
				c.AbortWithStatus(http.StatusInternalServerError)
				return
			}
		}

		userID, err := GetUserID(cookie, secret)
		if err != nil {
			if errors.Is(err, ErrNoUserInToken) {
				c.AbortWithStatus(http.StatusUnauthorized)
				return
			}
			if errors.Is(err, ErrTokenNotValid) {
				token, err := BuildJWTString(secret, uuid.New().String())
				if err != nil {
					logger.Error(ErrBuildJWTString, err)
					c.AbortWithStatus(http.StatusInternalServerError)
					return
				}
				userID, err = GetUserID(token, secret)
				if err != nil {
					logger.Error("Revalidate error user id from renewed token: %v", err)
					c.AbortWithStatus(http.StatusInternalServerError)
					return
				}
				c.SetCookie(CookieName, token, maxAge, "", "", false, true)
			}
		}

		c.Set(UserIDKey, userID)
		c.Next()
	}, nil
}

package postgres

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"log"
	"runtime"

	"github.com/golang-migrate/migrate/v4"
	_ "github.com/golang-migrate/migrate/v4/database/postgres"
	"github.com/golang-migrate/migrate/v4/source/iofs"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/rawen554/shortener/internal/models"
)

// DBStore - Интерфейс работы с пулом соединений.
type DBStore struct {
	conn *pgxpool.Pool
}

// CPUMultiplyer Мультипликатор для конфигурации максимального кол-ва соединений.
const CPUMultiplyer = 4

// ErrDBInsertConflict Обнаружен конфликт в БД, необходимо его обработать.
var ErrDBInsertConflict = errors.New("conflict insert into table, returned stored value")

// ErrURLDeleted Запрашиваемый URL удален.
var ErrURLDeleted = errors.New("url is deleted")

// NewPostgresStore Функция получения экземпляра DBStore.
func NewPostgresStore(ctx context.Context, dsn string) (*DBStore, error) {
	if err := runMigrations(dsn); err != nil {
		return nil, fmt.Errorf("failed to run DB migrations: %w", err)
	}

	conf, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to parse config from string: %w", err)
	}

	conf.MaxConns = int32(runtime.NumCPU() * CPUMultiplyer)

	conn, err := pgxpool.NewWithConfig(ctx, conf)
	if err != nil {
		return nil, fmt.Errorf("failed to create new conn pool: %w", err)
	}
	dbStore := &DBStore{conn: conn}

	return dbStore, nil
}

//go:embed migrations/*.sql
var migrationsDir embed.FS

// Применение миграций из папки в текущем каталоге - migrations.
func runMigrations(dsn string) error {
	d, err := iofs.New(migrationsDir, "migrations")
	if err != nil {
		return fmt.Errorf("failed to return an iofs driver: %w", err)
	}

	m, err := migrate.NewWithSourceInstance("iofs", d, dsn)
	if err != nil {
		return fmt.Errorf("failed to get a new migrate instance: %w", err)
	}
	if err := m.Up(); err != nil {
		if !errors.Is(err, migrate.ErrNoChange) {
			return fmt.Errorf("failed to apply migrations to the DB: %w", err)
		}
	}
	return nil
}

func (db *DBStore) Ping() error {
	if err := db.conn.Ping(context.Background()); err != nil {
		return fmt.Errorf("lost connection to db: %w", err)
	}
	return nil
}

func (db *DBStore) Close() {
	db.conn.Close()
}

func (db *DBStore) Get(id string) (string, error) {
	row := db.conn.QueryRow(context.Background(), "SELECT original_url, deleted_flag FROM shortener WHERE slug = $1", id)
	var result string
	var deleted bool
	err := row.Scan(&result, &deleted)
	if err != nil {
		return "", fmt.Errorf("cant scan result: %w", err)
	}

	if deleted {
		return "", ErrURLDeleted
	}

	return result, nil
}

func (db *DBStore) GetAllByUserID(userID string) ([]models.URLRecord, error) {
	result := make([]models.URLRecord, 0)

	rows, err := db.conn.Query(context.Background(), `
		SELECT slug, original_url
		FROM shortener
		WHERE user_id = $1 AND deleted_flag = FALSE
	`, userID)
	if err != nil {
		return nil, fmt.Errorf("failed to query all users records: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		record := models.URLRecord{}
		if err := rows.Scan(&record.ShortURL, &record.OriginalURL); err != nil {
			return nil, fmt.Errorf("cant scan records: %w", err)
		}

		result = append(result, record)
	}

	return result, nil
}

func (db *DBStore) DeleteMany(ids models.DeleteUserURLsReq, userID string) error {
	ctx := context.Background()

	query := `
		UPDATE shortener SET deleted_flag = TRUE
		WHERE shortener.slug = $1 AND shortener.user_id = $2`
	batch := &pgx.Batch{}
	for _, url := range ids {
		batch.Queue(query, url, userID)
	}
	batchResults := db.conn.SendBatch(ctx, batch)
	defer func() {
		if err := batchResults.Close(); err != nil {
			log.Printf("error closing result: %v", err)
		}
	}()

	for range ids {
		_, err := batchResults.Exec()
		if err != nil {
			log.Printf("error executing: %v", err)
			return fmt.Errorf("cant exec batch: %w", err)
		}
	}

	return nil
}

func (db *DBStore) Put(id string, url string, userID string) (string, error) {
	var err error

	row := db.conn.QueryRow(context.Background(), `
		INSERT INTO shortener VALUES ($1, $2, $3)
		ON CONFLICT (original_url)
		DO UPDATE SET
			original_url=EXCLUDED.original_url
		RETURNING slug
	`, id, url, userID)
	var result string
	if err := row.Scan(&result); err != nil {
		return "", fmt.Errorf("cant scan put record result: %w", err)
	}

	if id != result {
		err = ErrDBInsertConflict
	}

	return result, err
}

func (db *DBStore) PutBatch(urls []models.URLBatchReq, userID string) ([]models.URLBatchRes, error) {
	query := `
		INSERT INTO shortener VALUES (@slug, @originalUrl, @userID)
		ON CONFLICT (original_url)
		DO UPDATE SET
			original_url=EXCLUDED.original_url
		RETURNING slug
	`
	result := make([]models.URLBatchRes, 0)

	batch := &pgx.Batch{}
	for _, url := range urls {
		args := pgx.NamedArgs{
			"slug":        url.CorrelationID,
			"originalUrl": url.OriginalURL,
			"userID":      userID,
		}
		batch.Queue(query, args)
	}
	results := db.conn.SendBatch(context.Background(), batch)
	defer func() {
		if err := results.Close(); err != nil {
			log.Printf("error closing batch result: %v", err)
		}
	}()

	for _, url := range urls {
		id, err := results.Exec()
		if err != nil {
			return nil, fmt.Errorf("cant exec tx: %w", err)
		}
		result = append(result, models.URLBatchRes{
			CorrelationID: url.CorrelationID,
			ShortURL:      id.String(),
		})
	}

	return result, nil
}

func (db *DBStore) GetStats() (*models.Stats, error) {
	row := db.conn.QueryRow(context.Background(), "SELECT COUNT(*), COUNT(DISTINCT user_id) FROM shortener")
	var result models.Stats
	err := row.Scan(&result.URLs, &result.Users)
	if err != nil {
		return nil, fmt.Errorf("cant get stats: %w", err)
	}

	return &result, nil
}

package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/rawen554/shortener/internal/app"
	"github.com/rawen554/shortener/internal/config"
	"github.com/rawen554/shortener/internal/handlers"
	pb "github.com/rawen554/shortener/internal/handlers/proto"
	"github.com/rawen554/shortener/internal/logger"
	"github.com/rawen554/shortener/internal/logic"
	"github.com/rawen554/shortener/internal/store"
	"google.golang.org/grpc"
	"google.golang.org/grpc/reflection"
)

var (
	buildVersion = "N/A"
	buildDate    = "N/A"
	buildCommit  = "N/A"
)

const (
	timeoutServerShutdown = time.Second * 5
	timeoutShutdown       = time.Second * 10
)

func main() {
	ctx, cancelCtx := signal.NotifyContext(context.Background(), syscall.SIGQUIT, syscall.SIGTERM, syscall.SIGINT)

	logger, err := logger.NewLogger()
	if err != nil {
		log.Fatal(err)
	}

	logger.Infof("Build version: %s", buildVersion)
	logger.Infof("Build date: %s", buildDate)
	logger.Infof("Build commit: %s", buildCommit)

	defer cancelCtx()

	config, err := config.ParseFlags()
	if err != nil {
		logger.Fatal(err)
	}

	storage, err := store.NewStore(ctx, config)
	if err != nil {
		logger.Fatal(err)
	}

	wg := &sync.WaitGroup{}
	defer func() {
		wg.Wait()
	}()

	wg.Add(1)
	go func() {
		defer logger.Info("closed DB")
		defer wg.Done()
		<-ctx.Done()

		storage.Close()
	}()

	componentsErrs := make(chan error, 1)

	coreLogic := logic.NewCoreLogic(config, storage, logger.Named("logic"))
	a := app.NewApp(config, coreLogic, logger.Named("app"))

	r, err := a.SetupRouter()
	if err != nil {
		logger.Fatal(err)
	}
	srv := http.Server{
		Addr:    config.RunAddr,
		Handler: r,
	}

	go func(errs chan<- error) {
		if config.EnableHTTPS {
			_, errCert := os.ReadFile(config.TLSCertPath)
			_, errKey := os.ReadFile(config.TLSKeyPath)

			if errors.Is(errCert, os.ErrNotExist) || errors.Is(errKey, os.ErrNotExist) {
				privateKey, certBytes, err := app.CreateCertificates(logger.Named("certs-builder"))
				if err != nil {
					errs <- fmt.Errorf("error creating tls certs: %w", err)
					return
				}

				if err := app.WriteCertificates(certBytes, config.TLSCertPath, privateKey, config.TLSKeyPath, logger); err != nil {
					errs <- fmt.Errorf("error writing tls certs: %w", err)
					return
				}
			}

			if err := srv.ListenAndServeTLS(config.TLSCertPath, config.TLSKeyPath); err != nil {
				if errors.Is(err, http.ErrServerClosed) {
					return
				}
				errs <- fmt.Errorf("run tls server has failed: %w", err)
				return
			}
		}

		if err := srv.ListenAndServe(); err != nil {
			if errors.Is(err, http.ErrServerClosed) {
				return
			}
			errs <- fmt.Errorf("run server has failed: %w", err)
		}
	}(componentsErrs)

	if config.GRPCPort != "" {
		wg.Add(1)
		go func(errs chan<- error) {
			defer wg.Done()
			lis, err := net.Listen("tcp", fmt.Sprintf(":%s", config.GRPCPort))
			if err != nil {
				logger.Errorf("failed to listen: %w", err)
				errs <- err
				return
			}
			grpcServer := grpc.NewServer()
			reflection.Register(grpcServer)

			pb.RegisterShortenerServer(grpcServer, handlers.NewService(logger, coreLogic))

			logger.Infof("running gRPC service on %s", config.GRPCPort)

			if err = grpcServer.Serve(lis); err != nil {
				if errors.Is(err, grpc.ErrServerStopped) {
					return
				}
				errs <- err
			}
		}(componentsErrs)
	}

	wg.Add(1)
	go func() {
		defer logger.Info("server has been shutdown")
		defer wg.Done()
		<-ctx.Done()

		shutdownTimeoutCtx, cancelShutdownTimeoutCtx := context.WithTimeout(context.Background(), timeoutServerShutdown)
		defer cancelShutdownTimeoutCtx()
		if err := srv.Shutdown(shutdownTimeoutCtx); err != nil {
			logger.Errorf("an error occurred during server shutdown: %v", err)
		}
	}()

	select {
	case <-ctx.Done():
	case err := <-componentsErrs:
		logger.Error(err)
		cancelCtx()
	}

	go func() {
		ctx, cancelCtx := context.WithTimeout(context.Background(), timeoutShutdown)
		defer cancelCtx()

		<-ctx.Done()
		logger.Fatal("failed to gracefully shutdown the service")
	}()
}

